seen=set(); comps=[]
for r in range(H):
 for c in range(W):
  if g[r][c]!=0 or (r,c) in seen: continue
  q=[(r,c)];seen.add((r,c)); comp=[]; edge=False
  while q:
   x,y=q.pop();comp.append((x,y));edge |= x==0 or y==0 or x==H-1 or y==W-1
   for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
