    if 0<=a<H and 0<=b<W and g[a][b]==0 and (a,b) not in seen:seen.add((a,b));q.append((a,b))
  comps.append((comp,edge))
interiors=[comp for comp,e in comps if not e]
# Determine 1-components by 4-connectivity
